     ~S|function f(){ var a = [3, 1, 2]; return [typeof [].push, typeof [].map, typeof a.length, a.push === Array.prototype.push, a.map(x => x * 2).join(), 'push' in a, '0' in a, '01' in a, Object.keys(a).join()].join('/') } console.log(f())|},
